function updateTop(){document.getElementById('topStreak').textContent=db.stats.streak||0;document.getElementById('avatarText').textContent=(db.profile.avatar||db.profile.name[0]||'H').slice(0,1).toUpperCase();document.getElementById('profileNameTop').textContent=db.profile.name||'Learner';const xp=db.stats.xp||0;const level=Math.max(1,Math.floor(xp/500)+1);db.stats.level=level;document.getElementById('sideLevel').textContent=level;document.getElementById('sideXP').textContent=xp;document.getElementById('sideXpBar').style.width=((xp%500)/5)+'%';document.getElementById('sideLevelLabel').textContent=levelLabel(level)}
function levelLabel(n){return ['Beginner','Elementary','Pre-Intermediate','Intermediate','Upper-Intermediate','Advanced'][Math.min(5,Math.floor((n-1)/2))]||'Advanced'}
