function today(){return new Date().toISOString().slice(0,10)}
function touchStudy(){const d=today();if(db.stats.lastStudyDate!==d){const prev=db.stats.lastStudyDate?new Date(db.stats.lastStudyDate):null;const diff=prev?Math.round((new Date(d)-prev)/86400000):999;if(diff===1)db.stats.streak=(db.stats.streak||0)+1;else db.stats.streak=1;db.stats.lastStudyDate=d;}save()}
function addXP(n){db.stats.xp=(db.stats.xp||0)+n;touchStudy();}
function esc(s){return String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
