function saveVocab(id){const word=document.getElementById('mWord').value.trim();const meaning=document.getElementById('mMeaning').value.trim();if(!word||!meaning){toast('Vui lòng nhập từ và nghĩa.');return}const data={word,ipa:document.getElementById('mIpa').value.trim(),meaning,pos:document.getElementById('mPos').value.trim(),example:document.getElementById('mExample').value.trim(),exampleVi:document.getElementById('mExampleVi').value.trim(),topic:document.getElementById('mTopic').value.trim()||'daily',level:document.getElementById('mLevel').value,synonyms:document.getElementById('mSyn').value.trim(),antonyms:document.getElementById('mAnt').value.trim(),note:document.getElementById('mNote').value.trim()};if(id){Object.assign(db.vocab.find(v=>v.id===id),data)}else{db.vocab.unshift({id:uid(),...data,favorite:false,status:'New',reviewDue:null,createdAt:nowISO()})}save();closeModal();toast(id?'Đã cập nhật từ.':'Đã thêm từ mới.');render()}
function toggleFavWord(id){const v=db.vocab.find(x=>x.id===id);if(v){v.favorite=!v.favorite;save();render()}}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}
function renderSentences(){document.getElementById('view').innerHTML=shell('Học câu','Câu thực tế giúp bạn dùng tiếng Anh tự nhiên hơn.',`<div class="grid grid-2">${db.sentences.map(s=>`<div class="card"><div class="toolbar"><span class="badge">${esc(s.topic)}</span><button class="icon-btn" onclick="speak('${escapeJs(s.en)}')">🔊</button></div><h3>${esc(s.en)}</h3><p class="muted">${esc(s.vi)}</p><div class="chips"><span class="chip">${esc(s.grammar)}</span></div><div class="actions" style="margin-top:12px"><button class="btn btn-secondary" onclick="toggleFavSentence('${s.id}')">${s.favorite?'⭐ Đã lưu':'☆ Yêu thích'}</button><button class="btn btn-primary" onclick="speak('${escapeJs(s.en)}')">🔊 Nghe</button></div></div>`).join('')}</div><div class="card" style="margin-top:16px"><div class="toolbar"><div><h3 style="margin:0">Tự thêm câu</h3><div class="muted small">Lưu câu của riêng bạn để luyện sau.</div></div><button class="btn btn-primary" onclick="openSentenceModal()">＋ Thêm câu</button></div></div>`)}
function toggleFavSentence(id){const s=db.sentences.find(x=>x.id===id);if(s){s.favorite=!s.favorite;save();render()}}
function openSentenceModal(){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h3>Thêm câu</h3><button class="close" onclick="closeModal()">×</button></div><div class="form-grid"><div class="field full"><label>English sentence *</label><input id="sEn" class="input"/></div><div class="field full"><label>Dịch tiếng Việt *</label><input id="sVi" class="input"/></div><div class="field"><label>Topic</label><input id="sTopic" class="input" value="daily"/></div><div class="field"><label>Grammar</label><input id="sGrammar" class="input" value="Simple Present"/></div></div><div class="actions" style="justify-content:flex-end;margin-top:14px"><button class="btn btn-secondary" onclick="closeModal()">Hủy</button><button class="btn btn-primary" onclick="saveSentence()">Lưu câu</button></div></div></div>`}
function saveSentence(){const en=document.getElementById('sEn').value.trim(),vi=document.getElementById('sVi').value.trim();if(!en||!vi){toast('Vui lòng nhập câu và bản dịch.');return}db.sentences.push({id:uid(),en,vi,topic:document.getElementById('sTopic').value.trim()||'daily',grammar:document.getElementById('sGrammar').value.trim()||'N/A',favorite:false,createdAt:nowISO()});save();closeModal();toast('Đã thêm câu mới.');render()}
let flashIndex=0,flashFlipped=false;
function renderFlashcards(){const list=db.vocab;const v=list[flashIndex%list.length];document.getElementById('view').innerHTML=shell('Flashcards','Lật thẻ để ghi nhớ nhanh; tự đánh giá để lên lịch ôn.',`<div class="card"><div class="toolbar"><div><strong>${(flashIndex%list.length)+1} / ${list.length}</strong><div class="muted small">Chọn mức độ ghi nhớ sau khi lật thẻ.</div></div><button class="btn btn-secondary" onclick="shuffleFlash()">🔀 Đổi ngẫu nhiên</button></div><div class="flashcard ${flashFlipped?'flipped':''}" onclick="flashFlipped=!flashFlipped;renderFlashcards()"><div class="flash-inner"><div class="flash-face"><div class="big-word">${esc(v.word)}</div><div class="ipa">${esc(v.ipa||'')}</div><p class="muted">Nhấn để lật thẻ</p></div><div class="flash-face flash-back"><div class="big-word" style="font-size:31px">${esc(v.meaning)}</div><div class="ipa">${esc(v.pos||'')}</div><p class="example">${esc(v.example)}</p><p class="muted">${esc(v.exampleVi||'')}</p><button class="btn btn-secondary" onclick="event.stopPropagation();speak('${escapeJs(v.example||v.word)}')">🔊 Nghe</button></div></div></div><div class="rating"><button onclick="event.stopPropagation();rateFlash('Chưa nhớ')">😵 Chưa nhớ</button><button onclick="event.stopPropagation();rateFlash('Đã nhớ')">🙂 Đã nhớ</button><button onclick="event.stopPropagation();rateFlash('Rất dễ')">😎 Rất dễ</button></div></div>`)}
function rateFlash(status){const v=db.vocab[flashIndex%db.vocab.length];v.status=status;if(status==='Chưa nhớ')v.reviewDue=new Date(Date.now()+86400000).toISOString();else if(status==='Đã nhớ')v.reviewDue=new Date(Date.now()+3*86400000).toISOString();else v.reviewDue=new Date(Date.now()+7*86400000).toISOString();db.stats.wordsLearned=(db.stats.wordsLearned||0)+1;addXP(5);flashIndex=(flashIndex+1)%db.vocab.length;flashFlipped=false;save();toast('Đã lưu mức độ ghi nhớ.');renderFlashcards()}
function shuffleFlash(){flashIndex=Math.floor(Math.random()*db.vocab.length);flashFlipped=false;renderFlashcards()}
let quizState={items:[],index:0,score:0,selected:null,started:0};
function startQuiz(count=10){const pool=shuffle([...db.questions]);quizState={items:pool.slice(0,Math.min(count,pool.length)),index:0,score:0,selected:null,started:Date.now()};renderQuiz()}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function renderQuiz(){if(!quizState.items.length){document.getElementById('view').innerHTML=shell('Trắc nghiệm','Luyện từ vựng, ngữ pháp và câu.',`<div class="grid grid-3"><div class="card"><h3>10 câu</h3><p class="muted">Bài nhanh mỗi ngày.</p><button class="btn btn-primary" onclick="startQuiz(10)">Bắt đầu</button></div><div class="card"><h3>20 câu</h3><p class="muted">Luyện sâu hơn.</p><button class="btn btn-primary" onclick="startQuiz(20)">Bắt đầu</button></div><div class="card"><h3>Ngẫu nhiên</h3><p class="muted">Trộn tất cả dạng câu.</p><button class="btn btn-primary" onclick="startQuiz(999)">Bắt đầu</button></div></div><div class="card" style="margin-top:16px"><div class="notice">Kho hiện có <strong>${db.questions.length}</strong> câu trắc nghiệm được tạo từ bộ 500 từ. Bạn có thể thêm câu hỏi riêng trong Thư viện.</div></div>`);return}const q=quizState.items[quizState.index];const pct=Math.round((quizState.index/quizState.items.length)*100);document.getElementById('view').innerHTML=shell('Trắc nghiệm','Chọn đáp án rồi kiểm tra ngay.',`<div class="card"><div class="toolbar"><strong>Câu ${quizState.index+1} / ${quizState.items.length}</strong><span class="badge">${pct}%</span></div><div class="progress" style="margin:12px 0 20px"><div class="progress-bar" style="width:${pct}%"></div></div><h2 style="margin-top:0">${esc(q.prompt)}</h2><div class="option-grid">${q.options.map((o,i)=>`<button class="option ${quizState.selected===i?(i===q.answer?'correct':'wrong'):''}" onclick="selectQuiz(${i})">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div>${quizState.selected!==null?`<div class="notice" style="margin-top:16px">${quizState.selected===q.answer?'<span class="success-text"><strong>✓ Chính xác!</strong></span>':'<span class="danger-text"><strong>✗ Chưa đúng.</strong></span>'}<br/>${esc(q.explain)}</div><div class="actions" style="justify-content:flex-end;margin-top:14px"><button class="btn btn-primary" onclick="nextQuiz()">${quizState.index+1===quizState.items.length?'Xem kết quả':'Câu tiếp theo'}</button></div>`:''}</div>`)}
function selectQuiz(i){if(quizState.selected!==null)return;const q=quizState.items[quizState.index];quizState.selected=i;db.stats.answered=(db.stats.answered||0)+1;if(i===q.answer){quizState.score++;db.stats.correct=(db.stats.correct||0)+1;addXP(10)}else{vocabFromQuestion(q)}save();renderQuiz()}
function vocabFromQuestion(q){const w=db.vocab.find(v=>q.prompt.toLowerCase().includes(v.word.toLowerCase()));if(w){w.status='Review';w.reviewDue=new Date(Date.now()+86400000).toISOString()}}
function nextQuiz(){if(quizState.index+1>=quizState.items.length){db.stats.lessonsCompleted=(db.stats.lessonsCompleted||0)+1;addXP(50);const score=quizState.score;const total=quizState.items.length;db.history.push({id:uid(),type:'Quiz',score,total,date:nowISO()});save();quizState.items=[];document.getElementById('view').innerHTML=shell('Kết quả bài thi','Bạn vừa hoàn thành một phiên luyện tập.',`<div class="card" style="text-align:center"><div class="eyebrow">RESULT</div><div style="font-size:54px;font-weight:900">${score}/${total}</div><p class="muted">Tỷ lệ chính xác: ${Math.round(score/Math.max(1,total)*100)}%</p><div class="actions" style="justify-content:center;margin-top:14px"><button class="btn btn-primary" onclick="startQuiz(${total})">Làm lại</button><button class="btn btn-secondary" onclick="setView('review')">Ôn câu sai</button></div></div>`)}else{quizState.index++;quizState.selected=null;renderQuiz()}}
let listeningIndex=0;
function renderListening(){const list=db.sentences.filter(s=>s.en);if(!list.length){document.getElementById('view').innerHTML=shell('Luyện nghe','Chưa có câu luyện nghe.');return}const s=list[listeningIndex%list.length];const opts=shuffle([s.vi,...shuffle(list.filter(x=>x.id!==s.id)).slice(0,3).map(x=>x.vi)]);const answered=window.__listenAnswered||null;document.getElementById('view').innerHTML=shell('Luyện nghe','Luyện nghe với toàn bộ kho câu từ 500 từ vựng. Có phát chậm, phát nhanh và nghe–chọn.',`<div class="card"><div class="toolbar"><div><span class="badge">${esc(s.topic||'daily')}</span><div class="muted small">${listeningIndex+1} / ${list.length}</div></div><div class="actions"><button class="btn btn-secondary" onclick="speakSlow('${escapeJs(s.en)}',0.75)">🐢 0.75x</button><button class="btn btn-primary" onclick="speak('${escapeJs(s.en)}')">▶ Nghe</button><button class="btn btn-secondary" onclick="speakSlow('${escapeJs(s.en)}',1.25)">🐇 1.25x</button></div></div><div class="notice" style="margin-top:16px"><strong>Nghe & chọn nghĩa:</strong> nghe câu rồi chọn đáp án.</div><div class="quiz-options" style="margin-top:12px">${opts.map((o,i)=>`<button class="option-btn ${answered!==null&&o===s.vi?'correct':''}" onclick="answerListening('${escapeJs(o)}','${escapeJs(s.vi)}')">${esc(o)}</button>`).join('')}</div><div id="listenResult" class="notice" style="margin-top:12px">${answered?esc(answered):'Bạn có thể xem câu sau khi trả lời.'}</div><div class="actions" style="margin-top:14px"><button class="btn btn-secondary" onclick="showListeningText()">👁 Hiện câu</button><button class="btn btn-primary" onclick="nextListening()">Câu tiếp →</button></div><div id="listenText" class="card" style="margin-top:14px;display:none"><h3>${esc(s.en)}</h3><p class="muted">${esc(s.vi)}</p><p class="small muted">Từ trọng tâm: ${esc(s.vocabWord||'')}</p></div></div>`)}
function answerListening(choice,correct){const ok=choice===correct;window.__listenAnswered=ok?'✅ Chính xác!':'❌ Chưa đúng. Đáp án: '+correct;if(ok){db.stats.correct=(db.stats.correct||0)+1;db.stats.answered=(db.stats.answered||0)+1;addXP(5)}else{db.stats.answered=(db.stats.answered||0)+1}save();document.getElementById('listenResult').textContent=window.__listenAnswered}
function showListeningText(){const el=document.getElementById('listenText');if(el)el.style.display=el.style.display==='none'?'block':'none'}
function nextListening(){listeningIndex=(listeningIndex+1)%db.sentences.length;window.__listenAnswered=null;renderListening()}
function speakSlow(text,rate){if(!('speechSynthesis' in window)){toast('Không hỗ trợ đọc giọng nói.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=rate;speechSynthesis.speak(u)}
let speakingIndex=0;
function renderSpeaking(){const list=db.sentences.filter(s=>s.en);if(!list.length)return;const s=list[speakingIndex%list.length];document.getElementById('view').innerHTML=shell('Phát âm','Luyện nói theo từng câu trong toàn bộ bộ 500 từ. Nhận diện giọng nói chấm mức độ khớp văn bản.',`<div class="card"><div class="toolbar"><div><span class="badge">${esc(s.topic||'daily')}</span><div class="muted small">Câu ${speakingIndex+1} / ${list.length}</div></div><div class="actions"><button class="btn btn-secondary" onclick="prevSpeaking()">← Trước</button><button class="btn btn-secondary" onclick="nextSpeaking()">Tiếp →</button></div></div><h2 style="margin-top:18px">${esc(s.en)}</h2><p class="muted">${esc(s.vi)}</p><div class="notice" style="margin-top:12px"><strong>Từ trọng tâm:</strong> ${esc(s.vocabWord||'')} <span class="ipa" style="margin-left:8px">${esc((db.vocab.find(v=>v.word===s.vocabWord)||{}).ipa||'')}</span> <button class="btn btn-secondary" onclick="speak('${escapeJs(s.vocabWord||'')}')">🔊 Nghe từ</button></div><div class="actions" style="margin-top:14px"><button class="btn btn-primary" onclick="speak('${escapeJs(s.en)}')">🔊 Nghe mẫu</button><button class="btn btn-secondary" onclick="startRecognition()">🎙️ Bắt đầu nói</button></div><div id="speechResult" class="notice" style="margin-top:16px">Hãy nghe mẫu 1–2 lần rồi nói lại.</div></div><div class="grid grid-3" style="margin-top:16px"><div class="card"><div class="metric">${esc(s.grammar||'')}</div><div class="metric-label">Mẫu ngữ pháp</div></div><div class="card"><div class="metric">IPA</div><div class="metric-label">Từ trọng tâm: ${esc(s.vocabWord||'')}</div></div><div class="card"><div class="metric">500+</div><div class="metric-label">Câu luyện nói</div></div></div>`)}
function nextSpeaking(){speakingIndex=(speakingIndex+1)%db.sentences.length;renderSpeaking()}
function prevSpeaking(){speakingIndex=(speakingIndex-1+db.sentences.length)%db.sentences.length;renderSpeaking()}
function startRecognition(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Trình duyệt chưa hỗ trợ Speech Recognition. Hãy thử Chrome/Edge.');return}const target=db.sentences[speakingIndex%db.sentences.length]?.en||'I want to improve my English.';const r=new SR();r.lang='en-US';r.interimResults=false;r.maxAlternatives=1;r.onstart=()=>toast('Đang nghe...');r.onresult=e=>{const text=e.results[0][0].transcript;const score=similarity(text,target);if(score>=80){db.stats.correct=(db.stats.correct||0)+1;addXP(8)}db.stats.answered=(db.stats.answered||0)+1;save();document.getElementById('speechResult').innerHTML=`Bạn nói: <strong>${esc(text)}</strong><br/>Độ khớp câu: <strong>${score}%</strong><br/><span class="muted">Điểm này đo mức khớp văn bản, không phải điểm phát âm chuyên môn.</span>`;};r.onerror=()=>toast('Không nhận được giọng nói.');r.start()}
function similarity(a,b){const A=new Set(a.toLowerCase().replace(/[^a-z ]/g,'').split(/\s+/)),B=new Set(b.toLowerCase().replace(/[^a-z ]/g,'').split(/\s+/));let hit=0;B.forEach(x=>{if(A.has(x))hit++});return Math.round(hit/B.size*100)}
function renderGrammar(){document.getElementById('view').innerHTML=shell('Ngữ pháp','Giải thích đơn giản, công thức rõ và có ví dụ thực tế.',`<div class="grid grid-2">${db.grammar.map(g=>`<div class="card"><span class="badge">${esc(g.level)}</span><h3>${esc(g.title)}</h3><div class="notice"><strong>Công thức:</strong> ${esc(g.formula)}</div><p>${esc(g.explain)}</p><h4>Ví dụ</h4><div class="list">${g.examples.map(e=>`<div class="list-item">${esc(e)} <button class="icon-btn" onclick="speak('${escapeJs(e)}')">🔊</button></div>`).join('')}</div><p class="muted small"><strong>Lưu ý:</strong> ${esc(g.notes)}</p></div>`).join('')}</div>`)}
function renderCommunication(){document.getElementById('view').innerHTML=shell('Giao tiếp hằng ngày','Học theo tình huống, hội thoại và từ vựng quan trọng.',`<div class="grid grid-2">${db.communication.map(c=>`<div class="card"><span class="badge">${esc(c.topic)}</span><h3>${esc(c.title)}</h3><div class="list">${c.lines.map(l=>`<div class="list-item"><strong>${esc(l[0])}</strong> — ${esc(l[1])} <button class="icon-btn" onclick="speak('${escapeJs(l[1])}')">🔊</button></div>`).join('')}</div><div class="chips" style="margin-top:11px">${c.vocab.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div></div>`).join('')}</div>`)}
function renderTrilingual(){document.getElementById('view').innerHTML=shell('Tam ngữ Anh – Trung – Việt','Học cùng một ý bằng English, 中文 và Tiếng Việt.',`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>English</th><th>中文</th><th>Tiếng Việt</th><th>Topic</th><th></th></tr></thead><tbody>${db.trilingual.map(x=>`<tr><td><strong>${esc(x.en)}</strong></td><td>${esc(x.zh)}</td><td>${esc(x.vi)}</td><td><span class="badge">${esc(x.topic)}</span></td><td><button class="icon-btn" onclick="speak('${escapeJs(x.en)}')">🔊</button></td></tr>`).join('')}</tbody></table></div></div>`)}
function renderReview(){const due=db.vocab.filter(v=>v.reviewDue&&new Date(v.reviewDue)<=new Date());const hard=db.vocab.filter(v=>v.status==='Review'||v.status==='Chưa nhớ');document.getElementById('view').innerHTML=shell('Ôn tập thông minh','Ưu tiên nội dung bạn hay quên hoặc đã đến lịch ôn.',`<div class="grid grid-3"><div class="card"><div class="metric">${due.length}</div><div class="metric-label">Đến hạn hôm nay</div></div><div class="card"><div class="metric">${hard.length}</div><div class="metric-label">Cần củng cố</div></div><div class="card"><div class="metric">${db.vocab.filter(v=>v.status==='Rất dễ').length}</div><div class="metric-label">Đã nhớ tốt</div></div></div><div class="card" style="margin-top:16px"><div class="toolbar"><div><h3 style="margin:0">Danh sách ôn</h3><div class="muted small">Ôn nhanh bằng flashcard</div></div><button class="btn btn-primary" onclick="setView('flashcards')">Ôn ngay</button></div><div class="list" style="margin-top:12px">${[...due,...hard.filter(v=>!due.includes(v))].slice(0,12).map(v=>`<div class="list-item"><div class="toolbar"><div><strong>${esc(v.word)}</strong><span class="muted"> — ${esc(v.meaning)}</span></div><span class="badge">${esc(v.status)}</span></div></div>`).join('')||'<div class="empty">Chưa có nội dung cần ôn. Hãy làm quiz hoặc học flashcard.</div>'}</div></div>`)}
function renderLibrary(){document.getElementById('view').innerHTML=shell('Thư viện của tôi','Quản lý dữ liệu tự tạo và câu hỏi. Dữ liệu được lưu trên thiết bị.',`<div class="grid grid-3"><div class="card"><div class="metric">${db.vocab.length}</div><div class="metric-label">Từ vựng</div><button class="btn btn-primary" style="margin-top:12px" onclick="openVocabModal()">＋ Thêm từ</button></div><div class="card"><div class="metric">${db.sentences.length}</div><div class="metric-label">Câu</div><button class="btn btn-primary" style="margin-top:12px" onclick="openSentenceModal()">＋ Thêm câu</button></div><div class="card"><div class="metric">${db.questions.length}</div><div class="metric-label">Câu hỏi</div><button class="btn btn-primary" style="margin-top:12px" onclick="openQuestionModal()">＋ Thêm câu hỏi</button></div></div><div class="card" style="margin-top:16px"><h3>My Lessons</h3><p class="muted">Tạo bài học riêng từ các từ/câu bạn đã lưu.</p><button class="btn btn-secondary" onclick="openLessonModal()">＋ Tạo bài học</button><div class="list" style="margin-top:12px">${db.customLessons.map(l=>`<div class="list-item"><strong>${esc(l.title)}</strong><div class="muted small">${esc(l.note||'')}</div></div>`).join('')||'<div class="empty">Bạn chưa có bài học riêng.</div>'}</div></div><div class="card" style="margin-top:16px"><h3>Backup / Import / Export</h3><p class="muted">Sao lưu dữ liệu để không mất từ vựng và tiến độ.</p><div class="actions"><button class="btn btn-primary" onclick="downloadBackup()">⬇ Export JSON</button><button class="btn btn-secondary" onclick="document.getElementById('importFile').click()">⬆ Import JSON</button><input id="importFile" type="file" accept="application/json" hidden onchange="importBackup(event)"/><button class="btn btn-secondary" onclick="downloadCSV()">⬇ Export CSV</button></div></div>`)}
function openQuestionModal(){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h3>Thêm câu hỏi trắc nghiệm</h3><button class="close" onclick="closeModal()">×</button></div><div class="form-grid"><div class="field full"><label>Câu hỏi *</label><textarea id="qPrompt" class="textarea"></textarea></div>${[0,1,2,3].map(i=>`<div class="field"><label>Đáp án ${String.fromCharCode(65+i)} *</label><input id="q${i}" class="input"/></div>`).join('')}<div class="field"><label>Đáp án đúng (1-4)</label><select id="qAnswer" class="select"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></div><div class="field"><label>Topic</label><input id="qTopic" class="input" value="daily"/></div><div class="field full"><label>Giải thích</label><textarea id="qExplain" class="textarea"></textarea></div></div><div class="actions" style="justify-content:flex-end;margin-top:14px"><button class="btn btn-secondary" onclick="closeModal()">Hủy</button><button class="btn btn-primary" onclick="saveQuestion()">Lưu câu hỏi</button></div></div></div>`}
function saveQuestion(){const prompt=document.getElementById('qPrompt').value.trim();const opts=[0,1,2,3].map(i=>document.getElementById('q'+i).value.trim());if(!prompt||opts.some(x=>!x)){toast('Cần nhập câu hỏi và đủ 4 đáp án.');return}db.questions.push({id:uid(),type:'multiple',prompt,options:opts,answer:Number(document.getElementById('qAnswer').value),explain:document.getElementById('qExplain').value.trim()||'Hãy xem lại kiến thức liên quan.',topic:document.getElementById('qTopic').value.trim()||'daily',level:'Beginner'});save();closeModal();toast('Đã thêm câu hỏi.');render()}
function openLessonModal(){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h3>Tạo My Lesson</h3><button class="close" onclick="closeModal()">×</button></div><div class="field"><label>Tên bài học *</label><input id="lTitle" class="input" placeholder="Ví dụ: English giao tiếp cơ bản"/></div><div class="field" style="margin-top:12px"><label>Ghi chú</label><textarea id="lNote" class="textarea"></textarea></div><div class="field" style="margin-top:12px"><label>Chọn một số từ nổi bật</label><div class="chips">${db.vocab.slice(0,15).map(v=>`<label class="chip"><input type="checkbox" value="${v.id}"/> ${esc(v.word)}</label>`).join('')}</div></div><div class="actions" style="justify-content:flex-end;margin-top:14px"><button class="btn btn-secondary" onclick="closeModal()">Hủy</button><button class="btn btn-primary" onclick="saveLesson()">Tạo bài học</button></div></div></div>`}
function saveLesson(){const title=document.getElementById('lTitle').value.trim();if(!title){toast('Hãy nhập tên bài học.');return}const ids=[...document.querySelectorAll('#modalRoot input[type=checkbox]:checked')].map(x=>x.value);db.customLessons.push({id:uid(),title,note:document.getElementById('lNote').value.trim(),vocabIds:ids,createdAt:nowISO()});save();closeModal();toast('Đã tạo bài học.');render()}
function downloadBackup(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});downloadBlob(blob,'english-master-backup.json');toast('Đã xuất file sao lưu.')}
function downloadCSV(){const rows=[['word','ipa','meaning','pos','example','exampleVi','topic','level','status'],...db.vocab.map(v=>[v.word,v.ipa,v.meaning,v.pos,v.example,v.exampleVi,v.topic,v.level,v.status])];const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\n');downloadBlob(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'english-master-vocabulary.csv')}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importBackup(e){const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const incoming=JSON.parse(r.result);db={...db,...incoming,profile:{...db.profile,...incoming.profile},stats:{...db.stats,...incoming.stats}};save();toast('Đã nhập dữ liệu. Dữ liệu hiện tại được giữ lại và cập nhật theo bản sao lưu.');render()}catch{toast('File JSON không hợp lệ.')}};r.readAsText(file)}
function renderStats(){const accuracy=db.stats.answered?Math.round(db.stats.correct/db.stats.answered*100):0;document.getElementById('view').innerHTML=shell('Thống kê học tập','Theo dõi quá trình học theo cách dễ hiểu.',`<div class="grid grid-4">${[['Từ đã học',db.stats.wordsLearned],['Câu đã làm',db.stats.answered],['Độ chính xác',accuracy+'%'],['XP',db.stats.xp]].map(x=>`<div class="card metric-card"><div class="metric">${x[1]||0}</div><div class="metric-label">${x[0]}</div></div>`).join('')}</div><div class="grid grid-2" style="margin-top:16px"><div class="card"><h3>Tiến bộ kỹ năng</h3>${[['Vocabulary',Math.min(100,Math.round(db.stats.wordsLearned/10))],['Grammar',Math.min(100,accuracy)],['Listening',Math.min(100,accuracy)],['Speaking',0]].map(x=>`<div style="margin:14px 0"><div class="toolbar"><span>${x[0]}</span><strong>${x[1]}%</strong></div><div class="progress"><div class="progress-bar" style="width:${x[1]}%"></div></div></div>`).join('')}</div><div class="card"><h3>Lịch sử gần đây</h3><div class="list">${db.history.slice(-8).reverse().map(h=>`<div class="list-item"><strong>${esc(h.type)}</strong><div class="muted small">${new Date(h.date).toLocaleString('vi-VN')} · ${h.score}/${h.total}</div></div>`).join('')||'<div class="empty">Chưa có phiên luyện tập.</div>'}</div></div></div>`)}
function renderProfile(){document.getElementById('view').innerHTML=shell('Hồ sơ','Thông tin và thành tích học tập của bạn.',`<div class="grid grid-3"><div class="card"><div style="width:70px;height:70px;border-radius:22px;background:var(--primary);color:#fff;display:grid;place-items:center;font-size:28px;font-weight:900">${esc(db.profile.avatar||'H')}</div><h2>${esc(db.profile.name)}</h2><div class="badge">Level ${db.stats.level} · ${levelLabel(db.stats.level)}</div><div class="metric" style="margin-top:14px">${db.stats.xp} XP</div></div><div class="card"><h3>Thành tích</h3><div class="list">${(db.achievements||[]).map(a=>`<div class="list-item">🏆 ${esc(a)}</div>`).join('')||'<div class="empty">Hoàn thành các mục tiêu để mở khóa thành tích.</div>'}</div></div><div class="card"><h3>Thông tin học</h3><div class="kpi-list"><div class="kpi-row"><span>Streak</span><span>🔥 ${db.stats.streak}</span></div><div class="kpi-row"><span>Thời gian</span><span>${db.stats.totalStudyMinutes} phút</span></div><div class="kpi-row"><span>Bài hoàn thành</span><span>${db.stats.lessonsCompleted}</span></div></div></div></div><div class="card" style="margin-top:16px"><h3>Chỉnh hồ sơ</h3><div class="form-grid"><div class="field"><label>Tên hiển thị</label><input id="pName" class="input" value="${esc(db.profile.name)}"/></div><div class="field"><label>Avatar chữ cái</label><input id="pAvatar" maxlength="2" class="input" value="${esc(db.profile.avatar)}"/></div></div><button class="btn btn-primary" style="margin-top:12px" onclick="saveProfile()">Lưu hồ sơ</button></div>`)}
function saveProfile(){db.profile.name=document.getElementById('pName').value.trim()||'Learner';db.profile.avatar=document.getElementById('pAvatar').value.trim()||db.profile.name[0];save();toast('Đã cập nhật hồ sơ.');render()}
function renderSettings(){
  const cfg=getUpdateConfig();
  const safeUrl=esc(cfg.url||UPDATE_URL_DEFAULT);
  document.getElementById('view').innerHTML=shell('Cài đặt','Tùy chỉnh ứng dụng theo cách bạn học.',`
    <div class="card">
      <div class="form-grid">
        <div class="field"><label>Chế độ</label><select id="setTheme" class="select"><option value="light" ${db.profile.theme==='light'?'selected':''}>Light</option><option value="dark" ${db.profile.theme==='dark'?'selected':''}>Dark</option></select></div>
        <div class="field"><label>Mục tiêu từ/ngày</label><input id="setGoal" type="number" min="1" max="200" class="input" value="${db.profile.dailyGoal}"/></div>
        <div class="field"><label>Thông báo</label><select id="setNotify" class="select"><option value="1" ${db.profile.notifications?'selected':''}>Bật</option><option value="0" ${!db.profile.notifications?'selected':''}>Tắt</option></select></div>
        <div class="field"><label>Tốc độ giọng đọc</label><select id="setRate" class="select">${[0.5,0.75,1,1.25,1.5].map(x=>`<option ${Number(db.profile.speechRate)===x?'selected':''}>${x}</option>`).join('')}</select></div>
      </div>
      <div class="actions" style="margin-top:14px"><button class="btn btn-primary" onclick="saveSettings()">Lưu cài đặt</button><button class="btn btn-secondary" onclick="speak('This is your English practice session.')">🔊 Kiểm tra âm thanh</button></div>
    </div>

    <div class="card" style="margin-top:16px">
      <h3>☁️ Cập nhật dữ liệu</h3>
      <p class="muted">App tự kiểm tra dữ liệu online khi mở. Dữ liệu mới được <strong>thêm vào</strong>; tiến độ, yêu thích và dữ liệu bạn tự tạo được giữ nguyên.</p>
      <div id="updateStatus" style="margin:12px 0"></div>
      <div class="field"><label>Nguồn dữ liệu</label><input id="updateUrlInput" class="input" value="${safeUrl}" placeholder="https://.../version.json"/></div>
      <div class="muted small" style="margin-top:6px">Nguồn GitHub mặc định đã được cài sẵn cho English Master.</div>
      <div class="field" style="margin-top:12px"><label>Tự động kiểm tra khi mở app</label><select id="setAutoUpdate" class="select"><option value="1" ${db.profile.autoUpdate!==false?'selected':''}>Bật</option><option value="0" ${db.profile.autoUpdate===false?'selected':''}>Tắt</option></select></div>
      <div class="actions" style="margin-top:14px"><button class="btn btn-primary" onclick="saveUpdateSettings()">Lưu nguồn</button><button class="btn btn-secondary" onclick="checkForUpdates(false)">🔄 Kiểm tra cập nhật ngay</button></div>
      <div class="notice" style="margin-top:14px"><strong>Server hiện tại:</strong> <code>version.json</code> + <code>vocabulary.json</code>. Sau này có thể thêm các file dữ liệu khác mà không cần tải lại app.</div>
    </div>

    <div class="card" style="margin-top:16px"><h3>Dữ liệu</h3><div class="actions"><button class="btn btn-secondary" onclick="downloadBackup()">⬇ Sao lưu</button><button class="btn btn-danger" onclick="resetProgress()">↺ Reset tiến độ</button></div><p class="muted small">Reset tiến độ chỉ xóa XP, streak và lịch sử; từ vựng/câu/bài học cá nhân vẫn được giữ lại.</p></div>
  `);
  updateStatus();
}
function saveSettings(){db.profile.theme=document.getElementById('setTheme').value;db.profile.dailyGoal=Math.max(1,Number(document.getElementById('setGoal').value)||20);db.profile.notifications=document.getElementById('setNotify').value==='1';db.profile.speechRate=Number(document.getElementById('setRate').value);document.body.classList.toggle('dark',db.profile.theme==='dark');save();toast('Đã lưu cài đặt.');render()}
function resetProgress(){if(!confirm('Reset XP, streak, lịch sử và thống kê tiến độ? Từ vựng/câu sẽ giữ nguyên.'))return;db.stats={...clone(seed.stats)};db.history=[];save();toast('Đã reset tiến độ.');render()}
function openTopicModal(){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h3>Tạo chủ đề mới</h3><button class="close" onclick="closeModal()">×</button></div><div class="field"><label>Tên chủ đề</label><input id="topicNew" class="input" placeholder="Ví dụ: English for University"/></div><div class="actions" style="justify-content:flex-end;margin-top:14px"><button class="btn btn-secondary" onclick="closeModal()">Hủy</button><button class="btn btn-primary" onclick="saveTopic()">Tạo</button></div></div></div>`}
function saveTopic(){const t=document.getElementById('topicNew').value.trim();if(!t){toast('Hãy nhập tên chủ đề.');return}db.customTopics=db.customTopics||[];if(!db.customTopics.includes(t))db.customTopics.push(t);save();closeModal();toast('Đã tạo chủ đề.');renderHome()}
window.checkForUpdates=checkForUpdates;window.saveUpdateSettings=saveUpdateSettings;window.updateStatus=updateStatus;window.openVocabModal=openVocabModal;window.closeModal=closeModal;window.saveVocab=saveVocab;window.toggleFavWord=toggleFavWord;window.doVocabSearch=doVocabSearch;window.setView=setView;window.filterTopic=filterTopic;window.openSentenceModal=openSentenceModal;window.saveSentence=saveSentence;window.toggleFavSentence=toggleFavSentence;window.speak=speak;window.speakSlow=speakSlow;window.rateFlash=rateFlash;window.shuffleFlash=shuffleFlash;window.startQuiz=startQuiz;window.selectQuiz=selectQuiz;window.nextQuiz=nextQuiz;window.startRecognition=startRecognition;window.openQuestionModal=openQuestionModal;window.saveQuestion=saveQuestion;window.openLessonModal=openLessonModal;window.saveLesson=saveLesson;window.downloadBackup=downloadBackup;window.downloadCSV=downloadCSV;window.importBackup=importBackup;window.saveProfile=saveProfile;window.saveSettings=saveSettings;window.resetProgress=resetProgress;window.openTopicModal=openTopicModal;window.saveTopic=saveTopic;
